import mujoco, numpy as np, time
ref=open('model_ref.xml').read()
def build(o,extra=''):
    s=ref.replace('<compiler autolimits="true"/>','<compiler autolimits="true"/>\n  <option '+o+'>'+extra+'</option>')
    return s
def sim(m,seed):
    d=mujoco.MjData(m); n=int(2.0/m.opt.timestep)
    rng=np.random.default_rng(seed); d.qpos+=rng.normal(0,0.01,size=d.qpos.shape)
    mujoco.mj_forward(m,d)
    for _ in range(n): mujoco.mj_step(m,d)
    st=np.zeros(mujoco.mj_stateSize(m,mujoco.mjtState.mjSTATE_FULLPHYSICS))
    mujoco.mj_getState(m,d,st,mujoco.mjtState.mjSTATE_FULLPHYSICS); return st
mref=mujoco.MjModel.from_xml_path('model_ref.xml')
seeds=list(range(8))
refs=[sim(mref,s) for s in seeds]
cands={
 'base':build('solver="PGS" jacobian="dense" tolerance="1e-12"'),
 'nocontact':build('solver="PGS" jacobian="dense" tolerance="1e-12"','<flag contact="disable"/>'),
 'nocontact_novmax':build('solver="PGS" jacobian="dense" tolerance="1e-12"','<flag contact="disable"/>').replace('<config key="vmax" value="0.05"/>',''),
 'nocontact_nogeomcol':build('solver="PGS" jacobian="dense" tolerance="1e-12"','<flag contact="disable"/>').replace('condim="1"','condim="1" contype="0" conaffinity="0"'),
}
ms={k:mujoco.MjModel.from_xml_string(v) for k,v in cands.items()}
for k,m in ms.items():
    err=max(np.abs(sim(m,s)-r).max() for s,r in zip(seeds,refs))
    print(k,'err',f'{err:.2e}')
# interleaved timing
times={k:[] for k in list(ms)+['ref']}
for i in range(10):
    for k,m in list(ms.items())+[('ref',mref)]:
        t=time.perf_counter(); sim(m,i+100); times[k].append(time.perf_counter()-t)
tr=np.mean(times['ref'])
for k in ms: print(k,'pct',round(np.mean(times[k])/tr,3))
print('ref',round(tr,3))
EOF
